def test_error_classifier():
    """Test API error classification."""
    print("Testing _error_classifier...")

    # Test 1: Rate limit (429)
    class RateLimitError(Exception):
        status_code = 429

    result = classify_api_error(RateLimitError("rate limited"))
    assert result.reason == FailoverReason.rate_limit, f"Expected rate_limit, got {result.reason}"
    assert result.retryable is True

    # Test 2: Context overflow (400 + pattern)
    result = classify_response_error(400, {"error": {"message": "context length exceeded"}})
    assert result.reason == FailoverReason.context_overflow
    assert result.should_compress is True

    # Test 3: Billing (402 without transient signal)
    result = classify_response_error(402, {"error": {"message": "insufficient credits"}})
    assert result.reason == FailoverReason.billing
    assert result.retryable is False

    # Test 4: Transient 402 (usage limit with retry signal)
    result = classify_response_error(402, {"error": {"message": "usage limit, try again in 5 min"}})
    assert result.reason == FailoverReason.rate_limit
    assert result.retryable is True

    # Test 5: Auth (401)
    result = classify_response_error(401, {"error": {"message": "invalid api key"}})
    assert result.reason == FailoverReason.auth
    assert result.retryable is False

    # Test 6: Server error (500)
    result = classify_response_error(500, {"error": {"message": "internal error"}})
    assert result.reason == FailoverReason.server_error
    assert result.retryable is True

    # Test 7: Model not found (404)
    result = classify_response_error(404, {"error": {"message": "model not found"}})
    assert result.reason == FailoverReason.model_not_found
    assert result.retryable is False

    # Test 8: Timeout (from exception)
    class TimeoutErr(TimeoutError):
        pass

    result = classify_api_error(TimeoutErr("timed out"))
    assert result.reason == FailoverReason.timeout
    assert result.retryable is True

    # Test 9: ClassifiedError properties
    assert result.is_transient is True
    assert result.is_context_related is False

    print("  PASS: All error classifier tests")


def test_tool_call_parser():
    """Test raw tool call tag parsing."""
    print("Testing _tool_call_parser...")

    # Test 1: Hermes format
    content1 = '''I'll write a file.
<tool_call>{"name": "write_file", "arguments": {"path": "test.py", "content": "print(1)"}}</tool_call>
'''
    cleaned, calls = parse_tool_calls(content1)
    assert len(calls) == 1, f"Expected 1 call, got {len(calls)}"
    assert calls[0].name == "write_file"
    assert calls[0].arguments["path"] == "test.py"
    assert cleaned and "I'll write" in cleaned

    # Test 2: Multiple Hermes calls
    content2 = '''
<tool_call>{"name": "read_file", "arguments": {"path": "a.py"}}</tool_call>
<tool_call>{"name": "write_file", "arguments": {"path": "b.py", "content": "x"}}</tool_call>
'''
    cleaned, calls = parse_tool_calls(content2)
    assert len(calls) == 2, f"Expected 2 calls, got {len(calls)}"
    assert calls[0].name == "read_file"
    assert calls[1].name == "write_file"

    # Test 3: No tool calls
    content3 = "Just some text without any tool calls."
    cleaned, calls = parse_tool_calls(content3)
    assert len(calls) == 0
    assert cleaned == content3

    # Test 4: to_openai_format
    calls = [ParsedToolCall(id="call_123", name="write_file", arguments={"path": "x.py"})]
    openai_fmt = to_openai_format(calls)
    assert len(openai_fmt) == 1
    assert openai_fmt[0]["function"]["name"] == "write_file"
    assert openai_fmt[0]["type"] == "function"
    assert json.loads(openai_fmt[0]["function"]["arguments"])["path"] == "x.py"

    # Test 5: Empty content
    cleaned, calls = parse_tool_calls("")
    assert len(calls) == 0

    # Test 6: Generic XML format
    content6 = '<function_call name="run_command">{"command": "ls"}</function_call>'
    cleaned, calls = parse_tool_calls(content6)
    assert len(calls) == 1
    assert calls[0].name == "run_command"

    # Test 7: Malformed JSON with trailing comma (json_utils should repair)
    content7 = '<tool_call>{"name": "write_file", "arguments": {"path": "x.py",}}</tool_call>'
    cleaned, calls = parse_tool_calls(content7)
    # Should either parse (if json_repair installed) or skip gracefully
    assert len(calls) <= 1  # 0 or 1 depending on json_repair availability

    # Test 8: Completely invalid JSON (should skip gracefully)
    content8 = '<tool_call>not valid json at all</tool_call>'
    cleaned, calls = parse_tool_calls(content8)
    assert len(calls) == 0  # Should not crash, just return empty

    # Test 9: Mixed valid and invalid tool calls
    content9 = '''
<tool_call>{"name": "valid_call", "arguments": {}}</tool_call>
<tool_call>broken json here</tool_call>
<tool_call>{"name": "another_valid", "arguments": {"x": 1}}</tool_call>
'''
    cleaned, calls = parse_tool_calls(content9)
    assert len(calls) == 2  # Should extract valid ones, skip invalid
    assert calls[0].name == "valid_call"
    assert calls[1].name == "another_valid"

    # Test 10: JSON with unquoted keys (common LLM mistake)
    content10 = '<tool_call>{name: "read_file", arguments: {path: "test.py"}}</tool_call>'
    cleaned, calls = parse_tool_calls(content10)
    # Should either repair or skip gracefully
    assert len(calls) <= 1

    print("  PASS: All tool call parser tests")


def test_misuse_guard():
    """Test task spec misuse detection."""
    print("Testing _misuse_guard...")

    # Test 1: Wrong backend
    err = check_backend("gpt")
    assert err is not None
    assert err.correct_value == "codex"

    err = check_backend("anthropic")
    assert err is not None
    assert err.correct_value == "claude"

    err = check_backend("codex")  # Valid
    assert err is None

    # Test 2: Missing DoD
    err = check_dod_missing(None)
    assert err is not None
    assert err.error_type == "missing_dod"

    err = check_dod_missing({"command": "echo OK"})  # Valid
    assert err is None

    # Test 3: Design decision prompt
    err = check_design_decision("Should I use REST or GraphQL?")
    assert err is not None
    assert err.error_type == "design_decision"

    err = check_design_decision("Fix the bug in main.py")  # Valid
    assert err is None

    # Test 4: Full spec validation - wrong backend
    errors, warnings = validate_task_spec({
        "backend": "openai",
        "prompt": "test prompt for main.py with enough length to pass",
        "definition_of_done": {"command": "echo OK"},
    })
    assert len(errors) == 1
    assert errors[0].error_type == "wrong_backend"

    # Test 5: Valid spec
    errors, warnings = validate_task_spec({
        "backend": "codex",
        "prompt": "Fix the bug in src/main.py where foo() returns None instead of empty list",
        "definition_of_done": {"command": "python3 -c 'from src.main import foo; assert foo() == []'"},
    })
    assert len(errors) == 0

    # Test 6: Format errors message
    errors, warnings = validate_task_spec({"backend": "gpt"})
    msg = format_misuse_errors(errors, warnings)
    assert "MISUSE DETECTED" in msg
    assert "codex" in msg  # Should suggest correct backend

    print("  PASS: All misuse guard tests")


def test_backend_aliases():
    """Test Codex-era backend/model alias normalization."""
    print("Testing backend alias normalization...")

    assert normalize_backend_alias("gpt-5.5") == "codex"
    assert normalize_backend_alias("gpt-5.3-codex") == "codex"
    assert normalize_backend_alias("claude-sonnet-4-6") == "claude"
    assert normalize_backend_alias("text-gemini-oauth") == "gemini"
    assert backend_to_scillm_model("codex") == "gpt-5.5"
    assert backend_to_scillm_model("gemini") == "text-gemini-oauth"
    assert normalize_scillm_chat_url("http://localhost:4001") == "http://localhost:4001/v1/chat/completions"
    assert normalize_scillm_chat_url("http://localhost:4001/v1") == "http://localhost:4001/v1/chat/completions"

    spec = TaskSpec.model_validate({
        "task_id": "alias-test",
        "title": "Alias test",
        "prompt": "Fix the bug in src/main.py where foo returns the wrong value",
        "backend": "gpt-5.5",
        "cwd": str(Path.cwd()),
        "allowlist": ["src/main.py"],
        "definition_of_done": {"command": "echo OK", "assertion": "OK"},
    })
    assert spec.backend == "codex"

    print("  PASS: Backend aliases normalize correctly")


def test_tool_use_integration():
    """Test that tool_use.py imports all new modules correctly."""
    print("Testing tool_use.py integration...")

    # Import should not fail
    from tool_use import (
        _tool_result,
        _extract_reasoning,
        _retry_delay,
        VALID_TOOLS,
        DESTRUCTIVE_PATTERNS,
    )

    # Check _tool_result produces valid JSON
    result = _tool_result(ok=True, tool="write_file", path="test.py", lines_affected=10)
    parsed = json.loads(result)
    assert parsed["ok"] is True
    assert parsed["tool"] == "write_file"
    assert parsed["path"] == "test.py"

    # Check error result
    result = _tool_result(
        ok=False,
        tool="write_file",
        error_type="PERMISSION",
        error_message="Path not allowed",
        retryable=False,
    )
    parsed = json.loads(result)
    assert parsed["ok"] is False
    assert parsed["retryable"] is False
    assert "PERMISSION" in parsed["error_type"]

    # Check reasoning extraction
    msg1 = {"content": "hello", "reasoning_content": "thinking..."}
    assert _extract_reasoning(msg1) == "thinking..."

    msg2 = {"content": "<think>analyzing</think>response"}
    assert "analyzing" in _extract_reasoning(msg2)

    msg3 = {"content": "no reasoning here"}
    assert _extract_reasoning(msg3) is None

    # Check retry delay (should be > 0 and have some jitter)
    delays = [_retry_delay(1) for _ in range(10)]
    assert all(d > 0 for d in delays)
    assert len(set(delays)) > 1  # Jitter should create variation

    # Check VALID_TOOLS
    assert "write_file" in VALID_TOOLS
    assert "edit_file" in VALID_TOOLS
    assert "read_file" in VALID_TOOLS
    assert "run_command" in VALID_TOOLS

    # Check destructive patterns
    assert len(DESTRUCTIVE_PATTERNS) > 0

    print("  PASS: All tool_use integration tests")


